pub fn term_name(t: u16) -> &'static str {
    TERM_NAMES[t as usize]
}

pub fn nonterm_name(n: usize) -> &'static str {
    NONTERM_NAMES[n]
}

/// The left-hand side nonterminal of production `p`.
pub fn prod_lhs(p: usize) -> usize {
    LHS[p] as usize
}

/// The number of right-hand side symbols of production `p`.
pub fn prod_len(p: usize) -> usize {
    RHS_LEN[p] as usize
}

